	/// <summary>Every hero power, by name. See HeroPowerDatabase.All for the list form.</summary>
	public static class HSHeroPower
	{
		private static readonly Dictionary<int, CardEntry> ById = BuildIndex();

		/// <summary>The card with this dbf id, for a fixture that has an id and no name.</summary>
		public static CardEntry Get(int dbfId) => ById[dbfId];

		private static Dictionary<int, CardEntry> BuildIndex()
		{
			var index = new Dictionary<int, CardEntry>(HeroPowerDatabase.All.Count);
			foreach(var card in HeroPowerDatabase.All)
				index[card.DbfId] = card;
			return index;
		}

